from fractions import Fraction

count = int(input())
for i in range(count):
    k = int(input())
    terms = []
    for j in range(k):
        terms.append(int(input()))
    print(terms)
    d = terms[1] - terms[0]
    is_arithmetic = all(terms[j + 1] - terms[j] == d for j in range(k - 1))
    print(f"  d = {d}, every step adds d: {is_arithmetic}")
    if terms[0] == 0:
        print("  a_0 = 0, so there is no ratio")
        is_geometric = False
    else:
        r = Fraction(terms[1], terms[0])
        is_geometric = all(terms[j + 1] == r * terms[j] for j in range(k - 1))
        print(f"  r = {r}, every step multiplies by r: {is_geometric}")
    if is_arithmetic and is_geometric:
        print("  both")
    elif is_arithmetic:
        print("  arithmetic")
    elif is_geometric:
        print("  geometric")
    else:
        print("  neither")
